<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { useRoute } from 'vue-router';
import { api,ApiError } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { useSessionStore } from '../stores/session';
import { actionNames,m4Names } from '../domain/m4';
import { formatFen,shanghaiTime } from '../domain/m1';
import ErrorPanel from '../components/ErrorPanel.vue';
import M4Navigation from '../components/M4Navigation.vue';
import M4ConfirmAction from '../components/M4ConfirmAction.vue';
import M4EventGenerator from '../components/M4EventGenerator.vue';
const notice=ref('');
const eventAccepted=()=>{notice.value='Mock 事件已受理，等待后台独立核验。';void remote.load();};
const route=useRoute(),session=useSessionStore();const id=computed(()=>String(route.params.id));
const remote=useRemote(async()=>{const target=id.value;const result=await api.getAftersale(target);if(result.id!==target)throw new ApiError('INVALID_RESPONSE','售后记录与当前工单不符。');return result;});
watch(id,()=>{notice.value='';void remote.load();},{immediate:true});const action=ref('ACKNOWLEDGE');
const update=computed(()=>{const target=id.value,body={action:action.value,version:remote.data.value?.version??0};return (key:string)=>api.updateAftersale(target,body as never,key);});
const reconcile=computed(()=>{const target=id.value;return (key:string)=>api.reconcileAftersale(target,key);});
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">售后中心 / Mock 详情</p><h1>售后协调详情</h1><p class="muted">来源退款与供应商退款分别核验</p></div><el-button :loading="remote.loading.value" @click="remote.load">刷新权威状态</el-button></div><M4Navigation /><p v-if="notice" class="success-note" role="status">{{ notice }}</p><div v-if="remote.loading.value" role="status" class="panel data-state"><el-skeleton :rows="6" animated /></div><ErrorPanel v-else-if="remote.error.value" :error="remote.error.value" :title="remote.error.value.status===404?'售后不存在或不在访问范围':'售后详情读取失败'"><el-button @click="remote.load">重试</el-button></ErrorPanel><template v-else-if="remote.data.value"><section class="panel detail-panel"><h2>{{ remote.data.value.sourceCaseId }} · {{ m4Names[remote.data.value.type] }}</h2><dl class="order-facts"><div><dt>来源平台状态</dt><dd>{{ m4Names[remote.data.value.sourceState] }} · {{ remote.data.value.sourceState }}</dd></div><div><dt>本地工作流</dt><dd>{{ m4Names[remote.data.value.state] }} · {{ remote.data.value.state }}</dd></div><div><dt>供应商权威状态</dt><dd>{{ m4Names[remote.data.value.upstreamState] }} · {{ remote.data.value.upstreamState }}</dd></div><div><dt>申请金额 / 数量</dt><dd>{{ formatFen(remote.data.value.requestedRefundFen) }} CNY / {{ remote.data.value.qty }}</dd></div><div><dt>来源版本 / 工单版本</dt><dd>{{ remote.data.value.sourceVersion }} / {{ remote.data.value.version }}</dd></div><div><dt>时限 / 最近更新（上海）</dt><dd>{{ shanghaiTime(remote.data.value.deadlineAt) }} / {{ shanghaiTime(remote.data.value.updatedAt) }}</dd></div></dl><p class="freeze-note">上游已付、下游取消后进入协调，申请退款不能立即认定成功。付款 UNKNOWN 时先核验付款，禁止重复支付。</p><p class="help-text">安全原因码：{{ remote.data.value.reasonCode??'无' }}</p><RouterLink class="text-link" :to="`/orders/${remote.data.value.salesOrderId}`">查看关联销售订单</RouterLink><form v-if="session.can('aftersales.manage')" class="inline-form" @submit.prevent><label>协调动作<select v-model="action" name="aftersaleAction"><option v-for="(label,key) in actionNames" :key="key" :value="key">{{ label }}</option></select></label><M4ConfirmAction testid="aftersale-action" label="审核协调申请" :context="`${id}:${action}:${remote.data.value.version}`" :run="update" @done="remote.load" /><M4ConfirmAction label="查询售后权威状态" :context="id" :run="reconcile" @done="remote.load" /></form></section><section class="panel detail-panel"><h2>供应商协调记录</h2><p v-if="!remote.data.value.coordinations.length" class="help-text">无关联采购协调记录。</p><div v-for="item in remote.data.value.coordinations" :key="item.id" class="payment-attempt"><RouterLink class="text-link mono" :to="`/purchases/${item.purchaseOrderId}`">{{ item.purchaseOrderId }}</RouterLink><dl class="order-facts"><div><dt>本地协调状态</dt><dd>{{ m4Names[item.state] }} · {{ item.state }}</dd></div><div><dt>供应商来源权威状态</dt><dd>{{ m4Names[item.upstreamSourceState] }} · {{ item.upstreamSourceState }}</dd></div><div><dt>申请供应商退款 / 当前版本</dt><dd>{{ formatFen(item.requestedRefundFen) }} CNY / {{ item.version }}</dd></div><div><dt>取消权威引用</dt><dd>{{ item.cancellationReference??'尚无确认' }}</dd></div><div><dt>退款权威引用</dt><dd>{{ item.refundReference??'尚无确认' }}</dd></div><div><dt>更新时间（上海）</dt><dd>{{ shanghaiTime(item.updatedAt) }}</dd></div></dl></div></section><section class="panel detail-panel"><h2>独立退款记录</h2><p v-if="!remote.data.value.refunds.length" class="help-text">无已核验退款记录；申请金额不是实际退款。</p><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>方向</th><th>金额</th><th>核验状态</th><th>权威引用 / 时间（上海）</th></tr></thead><tbody><tr v-for="item in remote.data.value.refunds" :key="item.id"><td>{{ item.direction==='SALES'?'销售退款':'供应商退款' }}</td><td>{{ formatFen(item.amountFen) }} {{ item.currency }}</td><td>{{ item.state==='VERIFIED'?'Mock 权威已核验':item.state }}</td><td>{{ item.externalReference??'未取得' }}<small>{{ shanghaiTime(item.verifiedAt) }}</small></td></tr></tbody></table></div></section><template v-if="session.can('aftersales.simulate')"><M4EventGenerator kind="source" :target-id="remote.data.value.salesOrderId" :aftersale="remote.data.value" @done="eventAccepted" /><M4EventGenerator v-if="remote.data.value.coordinations.length" kind="supplier" :target-id="id" :aftersale="remote.data.value" @done="eventAccepted" /></template></template></div></template>
